mapper.update:
UPDATE PRODUCTION SET EMP_ID = #{empId}, PROD_QTY = #{prodQty}, LOSS_QTY = NVL(#{lossQty}, 0),
PROD_STATUS = CASE WHEN #{prodStatus} = '보류' THEN '보류' WHEN #{prodStatus} = '취소' THEN '취소' WHEN ( NVL(( SELECT SUM( CASE WHEN P2.PROD_ID != #{prodId} AND NVL(P2.PROD_STATUS, '완료') != '취소' THEN NVL(P2.PROD_QTY, 0) + NVL(P2.LOSS_QTY, 0) ELSE 0 END ) FROM PRODUCTION P2 WHERE P2.ORDER_ID = ( SELECT P3.ORDER_ID FROM PRODUCTION P3 WHERE P3.PROD_ID = #{prodId} ) ), 0) + NVL(#{prodQty}, 0) + NVL(#{lossQty}, 0) ) >= ( SELECT NVL(WO.ORDER_QTY, 0) FROM WORK_ORDER WO JOIN PRODUCTION P4 ON WO.ORDER_ID = P4.ORDER_ID WHERE P4.PROD_ID = #{prodId} ) THEN '완료' ELSE '진행중' END,
REMARK = #{remark}, UPDATED_DATE = SYSDATE WHERE PROD_ID = #{prodId}
